// DINOSAUR DATA: an array is an ordered list of values. Each object in this array stores the information for one dinosaur.
// The website uses this information to build the cards and the pop-up profiles.
const dinosaurs=[
{name:"Tyrannosaurus rex",short:"T. rex",latin:"Tyrannosaurus rex",emoji:"🦖",image:"data:image/webp;base64,",diet:"Carnivore",period:"Late Cretaceous",size:"About 12 m long",text:"T. rex was a large meat-eating theropod with powerful jaws, sharp teeth, and a strong sense of smell. Its tiny arms were short, but its legs and tail were powerful."},
{name:"Triceratops",short:"Triceratops",latin:"Triceratops horridus",emoji:"🦏",image:"data:image/webp;base64,",diet:"Herbivore",period:"Late Cretaceous",size:"About 8–9 m long",text:"Triceratops had a large bony frill and three facial horns. Its beak and rows of teeth helped it crop and chew tough plants."},
{name:"Stegosaurus",short:"Stegosaurus",latin:"Stegosaurus stenops",emoji:"🦕",image:"data:image/webp;base64,",diet:"Herbivore",period:"Late Jurassic",size:"About 7–9 m long",text:"Stegosaurus is known for the large plates along its back and the spiked tail often nicknamed a thagomizer. It ate plants and had a relatively small head."},
{name:"Brachiosaurus",short:"Brachiosaurus",latin:"Brachiosaurus altithorax",emoji:"🦒",image:"data:image/webp;base64,",diet:"Herbivore",period:"Late Jurassic",size:"Around 20 m long",text:"Brachiosaurus was a gigantic sauropod. Its front legs were longer than its hind legs, giving its body a sloping shape and helping it reach high vegetation."},
{name:"Velociraptor",short:"Velociraptor",latin:"Velociraptor mongoliensis",emoji:"🦎",image:"data:image/webp;base64,",diet:"Carnivore",period:"Late Cretaceous",size:"Roughly 2 m long",text:"Velociraptor was much smaller than its movie portrayals. It was a feathered predator with a curved claw on each hind foot and a long, stiff tail."},
{name:"Ankylosaurus",short:"Ankylosaurus",latin:"Ankylosaurus magniventris",emoji:"🐢",image:"data:image/webp;base64,",diet:"Herbivore",period:"Late Cretaceous",size:"About 6–8 m long",text:"Ankylosaurus was covered in bony armor and had a heavy tail club. Its low body and broad teeth suited it to eating low-growing plants."},
{name:"Spinosaurus",short:"Spinosaurus",latin:"Spinosaurus aegyptiacus",emoji:"🐊",image:"data:image/webp;base64,",diet:"Carnivore",period:"Cretaceous",size:"Large, over 14 m estimated",text:"Spinosaurus had a distinctive sail-like structure on its back and a long, narrow snout. Fossils suggest it was strongly adapted to life around water."},
{name:"Parasaurolophus",short:"Parasaurolophus",latin:"Parasaurolophus walkeri",emoji:"🦆",image:"https://upload.wikimedia.org/wikipedia/commons/f/f4/Life_reconstruction_of_Parasaurolophus_walkeri.png",diet:"Herbivore",period:"Late Cretaceous",size:"About 9–10 m long",text:"Parasaurolophus was a plant-eating dinosaur with a long, curved crest on its head. The crest may have helped produce sounds and identify members of its species."},
{name:"Compsognathus",short:"Compsognathus",latin:"Compsognathus longipes",emoji:"🐓",image:"https://upload.wikimedia.org/wikipedia/commons/9/93/Compsognathus_TD.png",diet:"Carnivore",period:"Late Jurassic",size:"About 1 m long",text:"Compsognathus was a small, lightly built theropod. Its fossils show that not all dinosaurs were giants; some were around the size of a chicken or turkey."}
];
// PAGE ELEMENTS: getElementById finds an HTML element by its unique id. These variables give JavaScript access to the page controls and card area.
const cards=document.getElementById('cards');
const search=document.getElementById('search');
const diet=document.getElementById('diet');
const favoritesOnly=document.getElementById('favoritesOnly');
const clearSaved=document.getElementById('clearSaved');
const storageNote=document.getElementById('storageNote');
// LOCAL STORAGE KEY: localStorage is browser storage that can keep small pieces of information after a page is closed.
// This name identifies the saved preferences belonging to this website.
const STORAGE_KEY='dinoDiscovery.preferences.v1';

// LOAD SAVED PREFERENCES: this function reads the visitor's saved settings from the browser.
// JSON is a text format for storing structured data; parse turns that text back into JavaScript data.
// Validation checks that saved values have the expected type and are safe to use.
// A try/catch prevents a storage problem or damaged saved data from stopping the website.
function readSaved(){
  try {
    const raw=localStorage.getItem(STORAGE_KEY);
    if(!raw) return {favorites:[],search:'',diet:'all',favoritesOnly:false};
    const data=JSON.parse(raw);
    const validDiets=['all','Carnivore','Herbivore','Omnivore'];
    const validNames=new Set(dinosaurs.map(d=>d.name));
    return {
      favorites:Array.isArray(data.favorites)?data.favorites.filter(n=>validNames.has(n)):[],
      search:typeof data.search==='string'?data.search.slice(0,100):'',
      diet:validDiets.includes(data.diet)?data.diet:'all',
      favoritesOnly:data.favoritesOnly===true
    };
  } catch { return {favorites:[],search:'',diet:'all',favoritesOnly:false}; }
}
// RESTORE THE VISITOR'S SETTINGS: let creates a variable whose value can change.
// A Set stores unique values, which makes it useful for keeping a list of favorite dinosaur names.
let saved=readSaved();
let favoriteNames=new Set(saved.favorites);
search.value=saved.search;
diet.value=saved.diet;
favoritesOnly.setAttribute('aria-pressed',String(saved.favoritesOnly));
// SAVE PREFERENCES: convert the current favorites and filter settings into JSON text, then store that text in the browser.
// The try/catch also lets the page explain what happened if browser storage is unavailable.
function savePreferences(){
  try {
    localStorage.setItem(STORAGE_KEY,JSON.stringify({
      favorites:[...favoriteNames],search:search.value.slice(0,100),diet:diet.value,
      favoritesOnly:favoritesOnly.getAttribute('aria-pressed')==='true'
    }));
    storageNote.textContent='Saved in this browser.';
  } catch {
    storageNote.textContent='Browser storage is unavailable. Your changes may not be saved.';
  }
}
// MAKE A TAG: createElement makes a new HTML element. This helper creates the small label used for diet, time period, and size.
// textContent inserts text safely instead of interpreting it as HTML.
function makeTag(text){const span=document.createElement('span');span.className='tag';span.textContent=text;return span;}
// RENDER THE CARDS: “render” means build or refresh what the visitor sees.
// This function applies the current search and filters, clears the old cards, and creates cards for matching dinosaurs.
function render(){
  const q=search.value.toLowerCase();
  const selectedDiet=diet.value;
  const showFavorites=favoritesOnly.getAttribute('aria-pressed')==='true';
  // filter makes a new list containing only dinosaurs that match all active filters.
  const shown=dinosaurs.filter(x=>(selectedDiet==='all'||x.diet===selectedDiet)
    &&(!showFavorites||favoriteNames.has(x.name))
    &&(`${x.name} ${x.period} ${x.diet}`).toLowerCase().includes(q));
  cards.replaceChildren();
  if(!shown.length){const empty=document.createElement('p');empty.textContent=showFavorites?'No saved favorites match your filters.':'No dinosaurs found. Try another search.';cards.append(empty);return;}
  // forEach runs the following instructions once for each dinosaur that passed the filters.
  shown.forEach(x=>{
    const article=document.createElement('article');article.className='dino-card';
    const art=document.createElement('div');art.className='card-art';art.setAttribute('aria-hidden','true');
    if(x.image){const img=document.createElement('img');img.src=x.image;img.alt=x.name;art.append(img);}else{art.textContent=x.emoji;}
    const body=document.createElement('div');body.className='card-body';
    const heading=document.createElement('h3');heading.textContent=x.short;
    const latin=document.createElement('div');latin.className='latin';latin.textContent=x.latin;
    const tags=document.createElement('div');tags.className='tags';tags.append(makeTag(x.diet),makeTag(x.period));
    const description=document.createElement('p');description.textContent=x.text.slice(0,105)+'…';
    const more=document.createElement('button');more.className='more';more.type='button';more.textContent='Discover more →';more.addEventListener('click',()=>openDino(x.name));
    const favorite=document.createElement('button');favorite.className='favorite-btn';favorite.type='button';
    // Keep the favorite button's label and accessibility information in sync with the saved favorite list.
    function updateFavoriteButton(){const active=favoriteNames.has(x.name);favorite.textContent=active?'★ Saved favorite':'☆ Add to favorites';favorite.setAttribute('aria-pressed',String(active));favorite.setAttribute('aria-label',(active?'Remove ':'Add ')+x.name+(active?' from':' to')+' favorites');}
    favorite.addEventListener('click',()=>{if(favoriteNames.has(x.name))favoriteNames.delete(x.name);else favoriteNames.add(x.name);updateFavoriteButton();savePreferences();if(favoritesOnly.getAttribute('aria-pressed')==='true'&&!favoriteNames.has(x.name))render();});
    updateFavoriteButton();body.append(heading,latin,tags,description,more,favorite);article.append(art,body);cards.append(article);
  });
}
// OPEN A DINOSAUR PROFILE: find the selected dinosaur and fill in the dialog (pop-up) with its full information.
function openDino(name){
  const x=dinosaurs.find(d=>d.name===name);if(!x)return;
  const modalImage=document.getElementById('modalEmoji');modalImage.replaceChildren();
  if(x.image){const img=document.createElement('img');img.src=x.image;img.alt=x.name;img.style.cssText='width:100%;max-height:230px;object-fit:cover;border-radius:14px';modalImage.append(img);}else{modalImage.textContent=x.emoji;}
  document.getElementById('modalName').textContent=x.name;
  document.getElementById('modalLatin').textContent=x.latin;
  document.getElementById('modalText').textContent=x.text;
  const modalTags=document.getElementById('modalTags');modalTags.replaceChildren();[x.diet,x.period,x.size].forEach(t=>modalTags.append(makeTag(t)));
  document.getElementById('details').showModal();
}
// EVENT LISTENERS: an event listener runs a function when something happens, such as typing, changing a menu, or clicking a button.
// Save the new search/filter settings and redraw the cards whenever a visitor changes a control.
search.addEventListener('input',()=>{savePreferences();render();});
diet.addEventListener('change',()=>{savePreferences();render();});
favoritesOnly.addEventListener('click',()=>{const next=favoritesOnly.getAttribute('aria-pressed')!=='true';favoritesOnly.setAttribute('aria-pressed',String(next));favoritesOnly.textContent=next?'★ Showing favorites':'☆ Show favorites';savePreferences();render();});
// CLEAR SAVED DATA: reset the controls and remove this website's saved preferences from localStorage.
clearSaved.addEventListener('click',()=>{
  favoriteNames.clear();search.value='';diet.value='all';favoritesOnly.setAttribute('aria-pressed','false');favoritesOnly.textContent='☆ Show favorites';
  try{localStorage.removeItem(STORAGE_KEY);storageNote.textContent='Saved favorites and preferences cleared.';}
  catch{storageNote.textContent='Could not clear browser storage.';}
  render();
});
// Close the dinosaur profile when its close button is clicked.
document.getElementById('close').addEventListener('click',()=>document.getElementById('details').close());
// INITIAL PAGE SETUP: show the correct favorites button label and display the first set of dinosaur cards.
favoritesOnly.textContent=favoritesOnly.getAttribute('aria-pressed')==='true'?'★ Showing favorites':'☆ Show favorites';
render();
